using AiBuddy.Install;
using System.IO.Compression;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;

return await new Audit213().Run();
sealed class Audit213 {
 readonly string work=Path.Combine(Environment.GetEnvironmentVariable("AI_BUDDY_INSTALLER_TEST_ROOT")??Path.GetTempPath(),"audit213-"+Guid.NewGuid().ToString("N"));
 readonly List<object> results=[];int failures;
 static void Assert(bool b,string message){if(!b)throw new Exception(message);}
 async Task Test(string name,Func<Task> test){try{await test();results.Add(new{name,ok=true});Console.WriteLine("PASS "+name);}catch(Exception e){failures++;results.Add(new{name,ok=false,error=e.ToString()});Console.WriteLine("FAIL "+name+": "+e.Message);}}
 sealed class Host:IAppHost {
  public Task Stop(string root,Installation? old,IProgress<InstallProgress>? p,CancellationToken c)=>Task.CompletedTask;
  public Task StartAndVerify(string root,Installation i,CancellationToken c){var profile=Path.Combine(DataPaths.Registered(root,i.DataPath,false),"settings.json");if(!File.Exists(profile))Json.Save(profile,new{fixture=true});return Task.CompletedTask;}
  public Task CreateShortcuts(string root,Installation i,CancellationToken c)=>Task.CompletedTask;
  public Task RemoveShortcuts(string root,CancellationToken c)=>Task.CompletedTask;
 }
 sealed class Handler(Func<HttpRequestMessage,HttpResponseMessage> action):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken c)=>Task.FromResult(action(r));}
 sealed class Fixture:IDisposable {
  public readonly string Dir,Root;public readonly InstallManifest Manifest;public readonly byte[] Bytes;public readonly string Hash;public readonly HttpClient Http;public readonly List<string> Requests=[];public readonly InstallEngine Engine;
  public Fixture(string parent,string name,string generation="same"){
   Dir=Path.Combine(parent,name);Root=Path.Combine(Dir,"install");Directory.CreateDirectory(Dir);
   Package Zip(string id,string mount,string path,string content,string? edition=null){var b=Encoding.UTF8.GetBytes(content);var archive=Path.Combine(Dir,id+".zip");using(var z=ZipFile.Open(archive,ZipArchiveMode.Create)){using var f=z.CreateEntry(path).Open();f.Write(b);}InstallFile[] files=[new(path,b.Length,Hashing.Bytes(b))];return new(id,"fixture",mount,id+".zip",new FileInfo(archive).Length,b.Length,Hashing.FileHash(archive).Result,[],files,Edition:edition,FilesSha256:Manifests.IndexHash(files));}
   var p=new[]{Zip("root","root","README.md",generation),Zip("runtime","runtime","AI Buddy.exe","runtime"),Zip("app30","build","main.cjs",generation,"30fps"),Zip("app60","build","main.cjs",generation,"60fps"),Zip("character","build","assets/pet.webp","unchanged")};
   Manifest=new(1,ReleaseIdentity.Version,"v"+ReleaseIdentity.Version,"lXiaoSel1/AI-Buddy","win32","x64",ReleaseIdentity.Version,1,"30fps","deepseek",["root","runtime"],new("AI Buddy.exe",p[1].Files[0].Sha256),[new("30fps","30fps","app30"),new("60fps","60fps","app60")],[new("deepseek","DeepSeek","character",new(){["30fps"]=[],["60fps"]=[]})],p);Bytes=JsonSerializer.SerializeToUtf8Bytes(Manifest,Json.Options);Hash=Hashing.Bytes(Bytes);File.WriteAllBytes(Path.Combine(Dir,ReleaseIdentity.ManifestFileName),Bytes);
   Http=new(new Handler(r=>{Requests.Add(Path.GetFileName(r.RequestUri!.LocalPath));return new(HttpStatusCode.OK){Content=new ByteArrayContent(File.ReadAllBytes(Path.Combine(Dir,Path.GetFileName(r.RequestUri.LocalPath))))};}));
   Engine=new(Manifest,Bytes,Hash,new Downloader(Http),new Host(),Path.Combine(Dir,"root.zip"),p=>new Uri("https://example.invalid/"+p.AssetName));
  }
  public InstallOptions Options(string? root=null,string? offline=null,string edition="30fps")=>new(root??Root,Path.Combine(Dir,"cache"),edition,["deepseek"],"deepseek",offline,false,false,Pipe:"audit213-fixture");
  public void Dispose()=>Http.Dispose();
 }
 public async Task<int> Run(){
  Directory.CreateDirectory(work);
  await Test("A1 manual upgrade reuses verified unchanged packages and reports actual download",async()=>{using var old=new Fixture(work,"manual-old","old");await old.Engine.Install(old.Options(),null,default);using var next=new Fixture(work,"manual-next","next");var options=next.Options(old.Root);var expected=next.Manifest.Packages.Where(p=>p.Id is "root" or "app30").Sum(p=>p.Bytes);Assert(next.Engine.Estimate(options).DownloadBytes==expected,"estimate must exclude reusable installed packages");await next.Engine.Install(options,null,default);Assert(next.Requests.Order().SequenceEqual(new[]{"app30.zip","root.zip"}),"unchanged runtime/resources must never download");});
  await Test("A2 extracted installation is an offline source for a fresh installation",async()=>{using var f=new Fixture(work,"local-source");await f.Engine.Install(f.Options(),null,default);f.Requests.Clear();var target=Path.Combine(work,"中文 local target");var options=f.Options(target,f.Root);Assert(f.Engine.Estimate(options).DownloadBytes==0,"expanded local source must report zero download");await f.Engine.Install(options,null,default);Assert(f.Requests.Count==0&&File.Exists(InstallEngine.RecordPath(target)),"offline source installs without HTTP");});
  await Test("A1 modified installed resource is repaired rather than reused",async()=>{using var f=new Fixture(work,"damaged-resource");var installed=await f.Engine.Install(f.Options(),null,default);File.WriteAllText(Path.Combine(f.Root,installed.Build,"assets/pet.webp"),"tampered");f.Requests.Clear();await f.Engine.Install(f.Options(),null,default);Assert(f.Requests.SequenceEqual(new[]{"character.zip"}),"only damaged resource must download");});
  await Test("A2 local upgrade preserves target data and never copies source data",async()=>{using var source=new Fixture(work,"local-upgrade-source","new");await source.Engine.Install(source.Options(),null,default);using var target=new Fixture(work,"local-upgrade-target","old");await target.Engine.Install(target.Options(),null,default);var profile=Path.Combine(target.Root,"local/data-v003/settings.json");File.WriteAllText(profile,"{\"targetOriginal\":true}");var before=await Hashing.FileHash(profile);source.Requests.Clear();await source.Engine.Install(source.Options(target.Root,source.Root),null,default);Assert(source.Requests.Count==0&&await Hashing.FileHash(profile)==before,"target personal data must survive local upgrade byte-for-byte");});
  await Test("A2 damaged local source rejects without network fallback",async()=>{using var f=new Fixture(work,"local-damaged");var installed=await f.Engine.Install(f.Options(),null,default);File.WriteAllText(Path.Combine(f.Root,installed.Build,"main.cjs"),"changed");f.Requests.Clear();try{await f.Engine.Install(f.Options(Path.Combine(work,"local-damaged-target"),f.Root),null,default);}catch(InvalidDataException){Assert(f.Requests.Count==0,"offline source never silently switches to network");return;}throw new Exception("damaged local source accepted");});
  await Test("A7 successful rollback consumes its previous-version action",async()=>{using var f=new Fixture(work,"rollback-once");await f.Engine.Install(f.Options(),null,default);await f.Engine.Install(f.Options(edition:"60fps"),null,default);await f.Engine.Rollback(f.Root,null,default);Assert(await f.Engine.RollbackBlocker(f.Root,default) is not null,"consumed rollback must be unavailable");});
  await Test("A6 downgrade refuses migrated legacy voice registry without confirmation",async()=>{using var f=new Fixture(work,"rollback-migration");var old=await f.Engine.Install(f.Options(),null,default);Json.Save(InstallEngine.RecordPath(f.Root),old with{Version="2.0.11"});var pointer=Json.Read<JsonElement>(Path.Combine(f.Root,"local/current-build.json"));var fields=pointer.Deserialize<Dictionary<string,JsonElement>>()!;fields["version"]=JsonSerializer.SerializeToElement("2.0.11");fields["appVersion"]=fields["version"];Json.Save(Path.Combine(f.Root,"local/current-build.json"),fields);await f.Engine.Install(f.Options(edition:"60fps"),null,default);Json.Save(Path.Combine(f.Root,"local/plugins/registry-v2.json"),new{schemaVersion=2,packages=new Dictionary<string,object>{{"ai-buddy.voice-breeze",new{sourceId="official",dataNamespace="legacy"}}}});try{await f.Engine.Rollback(f.Root,null,default);}catch(IncompatibleRollbackException){return;}throw new Exception("migrated voice downgrade must require confirmation");});
  await Test("B4 API rate limit falls back to locally verified published proof",async()=>{
   const string signature="-----BEGIN SSH SIGNATURE-----\nfixture\n-----END SSH SIGNATURE-----\n";var source=new string('a',40);var sha=new string('b',64);var version="9.0.0";var payload=$"object {source}\ntype commit\ntag v{version}\ntagger fixture <fixture@example.invalid> 0 +0000\n\nSource: {source}\nInstaller SHA-256: {sha}\nManifest SHA-256: {sha}\nChecksums SHA-256: {sha}\nApp Update Protocol: 1\nApp Bootstrap Protocol: 1\n";var release=new UpdateRelease(version,"v"+version,"https://github.com/lXiaoSel1/AI-Buddy/releases/tag/v"+version,"https://github.com/lXiaoSel1/AI-Buddy/releases/download/v"+version+"/AI-Buddy-Setup-"+version+"-win-x64.exe","AI-Buddy-Setup-"+version+"-win-x64.exe",123,sha,sha,source,new string('c',40),payload,signature,sha);int raw=0;
   using var http=new HttpClient(new Handler(r=>{if(r.RequestUri!.Host=="api.github.com"){var response=new HttpResponseMessage(HttpStatusCode.TooManyRequests);response.Headers.RetryAfter=new(TimeSpan.FromSeconds(60));return response;}if(r.RequestUri.Host=="github.com")return new(HttpStatusCode.NotFound);raw++;Assert(r.RequestUri.AbsoluteUri=="https://raw.githubusercontent.com/lXiaoSel1/AI-Buddy/main/app-release-proof.json","fixed fallback URL");return new(HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(new{schemaVersion=1,release},Json.Options))};}));var selected=await new UpdateDiscovery(http,verifySignature:(_,s)=>s==signature).Check(ReleaseIdentity.Version,default);Assert(selected?.Version==version&&raw==1,"signed fallback must work without API");
  });
  await Test("B8 mirror maps only HTTPS origin and retains the exact path/query",()=>{var settings=new NetworkSettings(GithubMirror:"https://mirror.example:8443",HuggingFaceMirror:"https://hf.example");var logical=new Uri("https://github.com/lXiaoSel1/AI-Buddy/releases/download/v2.0.13/a.zip?download=1");Assert(settings.RequestUrl(logical).AbsoluteUri=="https://mirror.example:8443/lXiaoSel1/AI-Buddy/releases/download/v2.0.13/a.zip?download=1","path/query changed");Assert(settings.RequestUrl(new Uri("https://api.github.com/repos/a")).Host=="api.github.com","API must not be rewritten");foreach(var value in new[]{"http://mirror.example","https://mirror.example/prefix","https://user@mirror.example","https://mirror.example/?q=1"})try{new NetworkSettings(GithubMirror:value).Validate();throw new Exception("invalid mirror accepted");}catch(InvalidDataException){}return Task.CompletedTask;});
  await Test("B8 real HTTP proxy route and direct mode use the selected transport",async()=>{
   var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;var lines=new List<string>();
   var serving=Task.Run(async()=>{for(int i=0;i<2;i++){using var client=await listener.AcceptTcpClientAsync();using var stream=client.GetStream();using var reader=new StreamReader(stream,Encoding.ASCII,false,4096,true);lines.Add((await reader.ReadLineAsync())!);while(!string.IsNullOrEmpty(await reader.ReadLineAsync())){}await stream.WriteAsync(Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\n\r\nok"));}});
   try{using var handler=new InstallerNetworkHandler();using var http=new HttpClient(handler){Timeout=TimeSpan.FromSeconds(8)};InstallerNetwork.Configure(new(Mode:"manual",ProxyUrl:$"http://127.0.0.1:{port}"));Assert(await http.GetStringAsync("http://never-resolves.invalid/proxy-check?q=1")=="ok","proxy request failed");InstallerNetwork.Configure(new(Mode:"direct"));Assert(await http.GetStringAsync($"http://127.0.0.1:{port}/direct-check")=="ok","direct request failed");await serving;Assert(lines[0]=="GET http://never-resolves.invalid/proxy-check?q=1 HTTP/1.1"&&lines[1]=="GET /direct-check HTTP/1.1","wrong proxy/direct route");Assert(handler.Routes.Length==2&&handler.Routes[0].LogicalUrl.Contains("never-resolves.invalid"),"request provenance missing");}finally{InstallerNetwork.Configure(new());listener.Stop();}
  });
  Json.Save(Path.Combine(work,"results.json"),new{passed=results.Count-failures,failed=failures,results});Console.WriteLine("RESULT "+work);return failures==0?0:1;
 }
}
